// Package webhook delivers hub events to the URLs the owner of a workspace
// subscribes: each matching event of the workspace, and of its task forks
// unless switched off, is sent as one signed HTTP POST, in seq order and at
// least once.
//
// A subscription is created, read and changed under
// /api/v1/workspaces/:slug/webhooks. Its signing secret is generated by the
// hub, shown once and stored only sealed under the operator's key, with
// package secret's SealValue. Every change of a subscription writes its
// parley.webhook.* event in the transaction of the change.
//
// Each active or failing subscription has a delivery loop of its own, which
// reads the event log by position (ADR 05) and is woken by the event
// component's notification of a commit.
//
// The hub composes the component in internal/hub/webhook.go: it creates the
// zero value while it composes, registers its keys, schema and routes, binds
// it in a start hook and runs its loops as background work.
package webhook

import (
	"crypto/x509"
	"log/slog"
	"net"

	"github.com/agent-fox-dev/parley/internal/buildinfo"
	"github.com/agent-fox-dev/parley/internal/event"
	"github.com/agent-fox-dev/parley/internal/metrics"
	"github.com/agent-fox-dev/parley/internal/scrub"
	"github.com/agent-fox-dev/parley/internal/secret"
	"github.com/agent-fox-dev/parley/internal/store"
)

// Deps are what the component works with: the transactional store, the
// event log it writes its events to, the operator's keys and whether secrets
// can be stored, its clock (nil for the system clock), its log (nil discards
// it), the loaded [webhooks] settings, the resolver that looks up the
// host of a destination (nil for the system's), the dialer that opens the
// connection of an attempt (nil for a *net.Dialer), the roots a
// receiver's certificate is verified against (nil for the system's; there is
// no setting that turns the verification off), the recorder every
// delivery attempt is counted with (nil discards the counts) and the hub's
// scrubber, which learns every signing secret the component generates or
// opens, so that no log line or event metadata can hold one (nil for none).
// Keys is a function so that the component reads the keys as they are when
// it needs them; nil is no key. Available nil means a current key is among
// Keys.
type Deps struct {
	Store     *store.Store
	Events    *event.Component
	Keys      func() secret.Keys
	Available func() bool
	Clock     event.Clock
	Logger    *slog.Logger
	Settings  Settings
	Resolver  Resolver
	Dialer    Dialer
	RootCAs   *x509.CertPool
	Recorder  metrics.Recorder
	Scrubber  *scrub.Scrubber
}

// Component is the event webhook feature. The hub creates its zero value
// while it composes, registers its routes, and binds it in a start hook.
type Component struct {
	deps   Deps
	sender *sender
	loops  loops
}

// Bind gives the component its dependencies, filling the defaults of the
// optional ones.
func (c *Component) Bind(d Deps) {
	if d.Clock == nil {
		d.Clock = event.SystemClock(nil)
	}
	if d.Logger == nil {
		d.Logger = slog.New(slog.DiscardHandler)
	}
	if d.Resolver == nil {
		d.Resolver = net.DefaultResolver
	}
	if d.Dialer == nil {
		d.Dialer = &net.Dialer{}
	}
	if d.Recorder == nil {
		d.Recorder = metrics.Discard
	}
	if d.Keys == nil {
		d.Keys = func() secret.Keys { return secret.Keys{} }
	}
	if d.Available == nil {
		keys := d.Keys
		d.Available = func() bool { return keys().Current != nil }
	}
	c.deps = d
	c.sender = newSender(d, buildinfo.Get().Version)
}

// learn hands the signing secret plain to the hub's scrubber, which then
// removes it from every later log line and event metadata.
func (c *Component) learn(plain string) {
	if c.deps.Scrubber != nil {
		c.deps.Scrubber.Add(plain)
	}
}
